CREATE TYPE partner_type AS ENUM ('imobiliaria','corretor_autonomo','assessor_investimento','arquiteto','engenheiro','contador','outro'); CREATE TYPE partner_status AS ENUM ('active','inactive'); CREATE TABLE partners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, type partner_type NOT NULL DEFAULT 'outro', phone text NOT NULL, email text, affiliated_agency text, website text, creci text, commission_rate numeric, notes text, status partner_status NOT NULL DEFAULT 'active', parent_partner_id uuid REFERENCES partners(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE partners ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admins can manage partners" ON partners FOR ALL TO authenticated USING (has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'admin'::app_role)); CREATE TABLE partner_interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partners(id) ON DELETE CASCADE, type text NOT NULL DEFAULT 'other', note text NOT NULL, interaction_date timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE partner_interactions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admins can manage partner interactions" ON partner_interactions FOR ALL TO authenticated USING (has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (has_role(auth.uid(), 'admin'::app_role)); ALTER TABLE clients ADD COLUMN partner_id uuid REFERENCES partners(id) ON DELETE SET NULL; ALTER TABLE property_submissions ADD COLUMN partner_id uuid REFERENCES partners(id) ON DELETE SET NULL;